import 'package:flutter/material.dart';

class MovieApp extends StatelessWidget {
  @override
  Widget build(BuildContext context) {
    return MaterialApp(
      title: 'Movie Posters',
      home: MovieGridScreen(),
      debugShowCheckedModeBanner: false,
    );
  }
}

class MovieGridScreen extends StatelessWidget {
  final List<Map<String, String>> movies = [
    {
      'title': 'Avengers',
      'image': 'data:image/jpeg;base64,'
    },
    {
      'title': 'Avengers: Infinity War',
      'image': 'data:image/jpeg;base64,'
    },
    {
      'title': 'Spider-Man',
      'image': 'data:image/jpeg;base64,'
    },
    {
      'title': 'Iron Man',
      'image': 'data:image/jpeg;base64,'
    },
    {
      'title': 'Avengers: Age of Ultron',
      'image': 'data:image/jpeg;base64,'
    },
    {
      'title': 'Doctor Strange',
      'image': 'data:image/jpeg;base64,'
    },
    {
      'title': 'Thor: Ragnarok',
      'image': 'data:image/jpeg;base64,'
    },
    {
      'title': 'Captain America: Civil War',
      'image': 'data:image/jpeg;base64,'
    },
    {
      'title': 'Black Panther',
      'image': 'data:image/jpeg;base64,'
    },
    {
      'title': 'Avengers ant man quantumania fanfiction',
      'image': 'data:image/jpeg;base64,'
    },
  ];

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text('Movie Posters')),
      body: Padding(
        padding: const EdgeInsets.all(8.0),
        child: GridView.builder(
          itemCount: movies.length,
          gridDelegate: SliverGridDelegateWithFixedCrossAxisCount(
            crossAxisCount: 2, // 2 posters per row
            mainAxisSpacing: 10,
            crossAxisSpacing: 10,
            childAspectRatio: 2 / 3, // Poster ratio
          ),
          itemBuilder: (context, index) {
            var movie = movies[index];
            return Card(
              elevation: 4,
              child: Column(
                crossAxisAlignment: CrossAxisAlignment.stretch,
                children: [
                  Expanded(
                    child: Image.network(
                      movie['image']!,
                      fit: BoxFit.cover,
                    ),
                  ),
                  Padding(
                    padding: const EdgeInsets.all(8.0),
                    child: Text(
                      movie['title']!,
                      style: TextStyle(
                        fontWeight: FontWeight.bold,
                        fontSize: 16,
                      ),
                      textAlign: TextAlign.center,
                    ),
                  )
                ],
              ),
            );
          },
        ),
      ),
    );
  }
}
